patch:
diff --git a/tools/check-emfile-handling-fix.js b/tools/check-emfile-handling-fix.js
new file mode 100644
index 0000000..18826e3
--- /dev/null
+++ b/tools/check-emfile-handling-fix.js
@@ -0,0 +1,65 @@
+/**
+ * @fileoverview Reproduction for eslint/eslint#19924: `--fix` crashes with
+ * EMFILE in ESLint.outputFixes when many files receive autofixes.
+ * Mirrors tools/check-emfile-handling.js, but every file has an
+ * autofixable problem (missing trailing newline -> eol-last).
+ */
+
+"use strict";
+
+const fs = require("node:fs");
+const { spawnSync, execSync } = require("node:child_process");
+const os = require("node:os");
+
+const OUTPUT_DIRECTORY = "tmp/emfile-fix-check";
+let FILE_COUNT = 15000;
+
+if (os.platform() !== "win32") {
+	FILE_COUNT = parseInt(execSync("ulimit -n").toString().trim(), 10) + 1;
+	if (os.platform() === "darwin") {
+		FILE_COUNT = Math.min(FILE_COUNT, 100000);
+	}
+}
+
+console.log(`Generating ${FILE_COUNT} files in ${OUTPUT_DIRECTORY}...`);
+fs.rmSync(OUTPUT_DIRECTORY, { recursive: true, force: true, maxRetries: 8 });
+fs.mkdirSync(OUTPUT_DIRECTORY, { recursive: true });
+for (let i = 0; i < FILE_COUNT; i++) {
+	// no trailing newline -> fixable by eol-last
+	fs.writeFileSync(`${OUTPUT_DIRECTORY}/file_${i}.js`, `// This is file ${i}`);
+}
+
+console.log("Running ESLint with --fix...");
+const { status, stderr } = spawnSync(
+	process.execPath,
+	[
+		"bin/eslint.js",
+		OUTPUT_DIRECTORY,
+		"--fix",
+		"--no-config-lookup",
+		"--rule",
+		"eol-last: [error, always]",
+	],
+	{ encoding: "utf8", maxBuffer: 256 * 1024 * 1024 },
+);
+process.stderr.write(stderr);
+
+let fixed = 0;
+for (let i = 0; i < FILE_COUNT; i++) {
+	if (fs.readFileSync(`${OUTPUT_DIRECTORY}/file_${i}.js`, "utf8").endsWith("\n")) {
+		fixed++;
+	}
+}
+fs.rmSync(OUTPUT_DIRECTORY, { recursive: true, force: true, maxRetries: 8 });
+
+console.log(`ESLint exit code: ${status}; files fixed: ${fixed}/${FILE_COUNT}`);
+if (/EMFILE|ENFILE/u.test(stderr) && /outputFixes/u.test(stderr)) {
+	console.error("❌ BUG REPRODUCED: EMFILE/ENFILE thrown from ESLint.outputFixes");
+	process.exit(1);
+}
+if (status === 0 && fixed === FILE_COUNT) {
+	console.log("✅ No EMFILE error; all files fixed.");
+	process.exit(0);
+}
+console.error("⚠️ Unexpected result (not the reported symptom).");
+process.exit(2);
